+/**
+ * Variance per item between two days (inclusive): theoretical use from the
+ * sales sold in those days against actual use (every consume movement).
+ * `difference` is actual minus theoretical. Items where both are 0 are left out.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (at) => {
+    const day = dayOf(at);
+    return day >= from && day <= to;
+  };
+  const theoretical = new Map();
+  for (const sale of store.data.sales ?? []) {
+    if (!inRange(sale.soldAt)) continue;
+    for (const n of saleUse(store, getDish(store, sale.dishId), sale.qty))
+      theoretical.set(n.itemId, (theoretical.get(n.itemId) ?? 0) + n.qty);
+  }
+  const actual = new Map();
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at) || !batchItem.has(m.batchId)) continue;
+    const itemId = batchItem.get(m.batchId);
+    actual.set(itemId, (actual.get(itemId) ?? 0) + m.qty);
+  }
+  const round3 = (n) => Math.round(n * 1000) / 1000;
+  return listItems(store)
+    .map((item) => {
+      const t = round3(theoretical.get(item.id) ?? 0);
+      const a = round3(actual.get(item.id) ?? 0);
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: round3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
