+// Sales from the till: each dish sold uses one portion of its recipe per
+// unit sold. A ticket is booked once; booking is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been booked. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Ingredient quantities used by `qty` portions of a dish. */
+export function saleUse(store, dish, qty) {
+  return scaled(getRecipe(store, dish.recipeId), qty);
+}
+
+/**
+ * Books sale lines { ticket, soldAt, dish, qty, row }: checks that every
+ * ingredient lasts for all lines first (throwing sale_out_of_stock naming the
+ * row where it runs out), then consumes with ref "sale:<ticket>" at `soldAt`.
+ * Returns { tickets, dishes } booked.
+ */
+export function bookSales(store, lines) {
+  const needed = new Map();
+  for (const line of lines) {
+    for (const n of saleUse(store, line.dish, line.qty)) {
+      const total = round3((needed.get(n.itemId) ?? 0) + n.qty);
+      const available = round3(onHand(store, n.itemId));
+      if (available < total) {
+        const item = getItem(store, n.itemId);
+        throw new AppError("sale_out_of_stock", { row: line.row, item: item.name, available, unit: item.unit });
+      }
+      needed.set(n.itemId, total);
+    }
+  }
+  const before = structuredClone(store.data);
+  store.data.sales ??= [];
+  const tickets = new Set();
+  let dishes = 0;
+  try {
+    for (const line of lines) {
+      for (const n of saleUse(store, line.dish, line.qty))
+        if (n.qty > 0) consume(store, n.itemId, n.qty, { at: line.soldAt, ref: `sale:${line.ticket}` });
+      store.data.sales.push({ id: store.nextId("sale"), ticket: line.ticket, soldAt: line.soldAt, dishId: line.dish.id, qty: line.qty });
+      tickets.add(line.ticket);
+      dishes += line.qty;
+    }
+  } catch (e) {
+    store.data = before;
+    throw e;
+  }
+  return { tickets: tickets.size, dishes };
+}
